export class WorkItemRequestTimes {
  private readonly requestedAt = new Map<string, number>();

  record(workItemIds: readonly string[], requestedAt: number): void {
    for (const workItemId of workItemIds) {
      if (!this.requestedAt.has(workItemId)) {
        this.requestedAt.set(workItemId, requestedAt);
      }
    }
  }

  elapsedSinceRequestMs(
    workItemId: string,
    at: number | undefined,
  ): number | null {
    const requestedAt = this.requestedAt.get(workItemId);
    if (requestedAt === undefined || at === undefined) return null;
    return at - requestedAt;
  }
}
